from unittest.mock import AsyncMock, patch; from uuid import uuid4; import pytest; from httpx import AsyncClient; from sqlalchemy import select; from sqlalchemy.exc import IntegrityError; from sqlalchemy.ext.asyncio import AsyncSession; from src.extraction import BankStatementStatus; from src.identity import User, create_access_token; from tests.factories import StatementSummaryFactory; pytestmark = pytest.mark.asyncio
async def test_delete_current_user_removes_authenticated_user(client: AsyncClient, db: AsyncSession, test_user: User) -> None: 'AC8.13.109'; response = await client.delete(f'/users/{test_user.id}'); assert response.status_code == 204; await db.refresh(test_user); assert test_user.is_deleted is True; followup = await client.get('/users'); assert followup.status_code == 401
async def test_delete_user_does_not_allow_cross_user_deletion(public_client: AsyncClient, db: AsyncSession, test_user: User) -> None: 'AC8.13.109'; other_user = User(email=f'other-{uuid4()}@example.com', hashed_password='hashed'); db.add(other_user); await db.commit(); await db.refresh(other_user); token = create_access_token(data={'sub': str(test_user.id)}); response = await public_client.delete(f'/users/{other_user.id}', headers={'Authorization': f'Bearer {token}'}); assert response.status_code == 404; assert await db.scalar(select(User.id).where(User.id == other_user.id)) == other_user.id
async def test_delete_user_with_immutable_entries_returns_409(client: AsyncClient, test_user: User) -> None:
    'AC-ledger.14.6'; immutable_violation = IntegrityError('DELETE FROM users WHERE users.id = $1::UUID', {}, Exception('cannot delete immutable journal entry ... with status reconciled'))
    with patch.object(AsyncSession, 'commit', new_callable=AsyncMock, side_effect=immutable_violation): response = await client.delete(f'/users/{test_user.id}')
    assert response.status_code == 409
async def test_AC13_23_1_delete_user_with_in_flight_parse_returns_409(client: AsyncClient, db: AsyncSession, test_user: User) -> None: 'AC-extraction.123.1'; await StatementSummaryFactory.create_async(db, user_id=test_user.id, status=BankStatementStatus.PARSING); await db.commit(); response = await client.delete(f'/users/{test_user.id}'); assert response.status_code == 409; assert 'pars' in response.json()['detail'].lower(); assert await db.scalar(select(User.id).where(User.id == test_user.id)) == test_user.id
async def test_AC13_23_1_delete_user_without_in_flight_parse_succeeds(client: AsyncClient, db: AsyncSession, test_user: User) -> None: 'AC-extraction.123.1'; await StatementSummaryFactory.create_async(db, user_id=test_user.id, status=BankStatementStatus.PARSED); await db.commit(); response = await client.delete(f'/users/{test_user.id}'); assert response.status_code == 204; assert await db.scalar(select(User.id).where(User.id == test_user.id, User.is_deleted.is_(False))) is None
async def test_soft_delete_preserves_user_row_and_revokes_access(client: AsyncClient, db: AsyncSession, test_user: User) -> None: response = await client.delete(f'/users/{test_user.id}'); assert response.status_code == 204; get_res = await client.get('/users'); assert get_res.status_code == 401; await db.refresh(test_user); assert test_user.is_deleted is True
async def test_update_user_email_collision_with_soft_deleted_user_rejected(client: AsyncClient, db: AsyncSession, test_user: User) -> None: deleted_email = f'deleted-{uuid4()}@example.com'; deleted_user = User(email=deleted_email, hashed_password='hashed', is_deleted=True); db.add(deleted_user); await db.commit(); response = await client.put(f'/users/{test_user.id}', json={'email': deleted_email}); assert response.status_code == 400; assert 'Invalid update data' in response.json()['detail']
async def test_update_user_db_integrity_error_handled(client: AsyncClient, test_user: User) -> None:
    with patch.object(AsyncSession, 'commit', side_effect=IntegrityError('duplicate key', params={}, orig=Exception('duplicate key'))): response = await client.put(f'/users/{test_user.id}', json={'email': 'new_email@example.com'}); assert response.status_code == 400; assert 'Invalid update data' in response.json()['detail']
